{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C08", "C47", "C12", "C18", "C03", "C116", "C120", "C110", "C145"],
  "contradictory_card_ids": ["C27"],
  "prediction_basis_card_ids": ["C08", "C47", "C12", "C18", "C03", "C116"],
  "claims": [
    {
      "claim": "The closest fed-state context, KNI-272, gave absolute oral bioavailability of 36.4% as a post-prandial capsule in patients, directly supporting F ≥ 20% for this peptidomimetic scaffold.",
      "card_ids": ["C08"]
    },
    {
      "claim": "Additional KNI-272 fed capsule data at 4 mg/kg gave 22.06%, while the 2 mg/kg syrup gave 15.72%, showing formulation and dose dependence rather than a class-level low outcome.",
      "card_ids": ["C47", "C27"]
    },
    {
      "claim": "Atazanavir with food has >90% oral bioavailability and paritaprevir tablet F was 52.6%, supporting adequate oral absorption for HIV protease inhibitor peptidomimetics.",
      "card_ids": ["C12", "C18", "C03"]
    },
    {
      "claim": "L4 saquinavir records show high Caco-2 permeability (4.68 × 10^-5 cm/s) and improved solubility/dissolution for salt and cyclodextrin formulations, supporting adequate intestinal absorption for the closely related decahydroisoquinoline/tert-butylamide scaffold; these are formulation- and salt-specific and are not direct query F measurements.",
      "card_ids": ["C116", "C120", "C110", "C145"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C116", "C120", "C110", "C145"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific solubility or permeability measurement is available; L4 records are mostly for saquinavir salts, cyclodextrin complexes, or unrelated molecules.",
    "First-pass metabolism and gut-wall extraction for the query are not directly measured.",
    "The fed-state effect on the query's solubility and dissolution is not directly measured.",
    "KNI-272 fed-state F data are based on small sample sizes and show formulation dependence."
  ],
  "decision_summary": "L4 intestinal absorption and permeability records, especially saquinavir Caco-2 permeability and salt/dissolution data, support adequate absorption for the closely related decahydroisoquinoline/tert-butylamide scaffold, but are formulation-specific and not direct query F measurements. Combined with the closest fed KNI-272 capsule F of 36.4% and fed atazanavir >90%, the high prediction is retained and modestly strengthened; no affirmative threshold-relevant evidence supports F < 20% for the query."
}

